<?php
require_once __DIR__ . '/../../lib/admin.php'; $adminId=requireAdmin(); $input=requireJsonRequest(); requireCsrf(); $id=filter_var($input['id']??null,FILTER_VALIDATE_INT); $status=cleanText($input['status']??'',20); $note=cleanText($input['note']??'',500); $allowed=['new','contacted','confirmed','completed','cancelled','rejected']; if(!$id||!in_array($status,$allowed,true)) errorResponse(422,'VALIDATION_ERROR','Choose a valid booking and status.');
try{$db=getDatabaseConnection();$db->begin_transaction();$s=$db->prepare('SELECT status FROM bookings WHERE id=? FOR UPDATE');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();if(!$row){$db->rollback();errorResponse(404,'NOT_FOUND','Booking not found.');}$old=$row['status'];$u=$db->prepare('UPDATE bookings SET status=? WHERE id=?');$u->bind_param('si',$status,$id);$u->execute();$h=$db->prepare('INSERT INTO booking_status_history (booking_id,old_status,new_status,changed_by_admin_id,note) VALUES (?,?,?,?,NULLIF(?,\'\'))');$h->bind_param('issis',$id,$old,$status,$adminId,$note);$h->execute();$db->commit();successResponse(200,['id'=>$id,'status'=>$status]);}catch(Throwable $e){if(isset($db))$db->rollback();error_log('Status update failed: '.$e->getMessage());errorResponse(500,'UPDATE_FAILED','We could not update this booking.');}
